style.css:
@-moz-document url-prefix("http://"), url-prefix("https://") {
/* 繁體中文 (台灣、香港、澳門) */
    body :lang(zh), 
    body :lang(zh-HK), 
    body :lang(zh-TW),
    html[lang="zh"], 
    html[lang="zh-HK"], 
    html[lang="zh-TW"],
    [lang="zh"], 
    [lang="zh-HK"], 
    [lang="zh-TW"] {
        font-family: "Noto Sans CJK TC", sans-serif !important;
    }

    /* 簡體中文 (中國、新加坡) */
    body :lang(zh-CN), 
    body :lang(zh-SG),
    html[lang="zh-CN"], 
    html[lang="zh-SG"],
    [lang="zh-CN"], 
    [lang="zh-SG"] {
        font-family: "Noto Sans CJK SC", sans-serif !important;
    }
}
